def test_build_fallback_diagram_structure():
    results = [
        {
            "class": "MyClass",
            "method": "do_thing",
            "type": "function",
            "source": "path/to/file.py",
            "start_line": 10,
        }
    ]
    diagram = m.build_fallback_diagram(results)
    lines = diagram.split("\n")
    assert lines[0] == "graph TD"
    assert lines[1] == '    Q["Your question"]'
    assert '    U1["MyClass::do_thing"]' in lines
    assert '    F1["file.py:10"]' in lines
    assert "    Q --> U1" in lines
    assert "    U1 -. defined in .-> F1" in lines


